USE sentinel_ai_security;
CREATE TABLE IF NOT EXISTS vehicles (
    vehicle_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vehicle_uuid CHAR(36) NOT NULL, company_id BIGINT UNSIGNED NOT NULL, registration_number VARCHAR(30) NOT NULL, make VARCHAR(80) NULL, model VARCHAR(80) NULL, color VARCHAR(40) NULL, vehicle_status ENUM('ACTIVE','BLOCKED','ARCHIVED') NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, deleted_at TIMESTAMP NULL,
    CONSTRAINT fk_vehicles_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, UNIQUE KEY uq_vehicles_uuid (vehicle_uuid), UNIQUE KEY uq_vehicles_company_registration (company_id,registration_number), INDEX idx_vehicles_company_status (company_id,vehicle_status), INDEX idx_vehicles_company_deleted_at (company_id,deleted_at)
);
CREATE TABLE IF NOT EXISTS access_events (
    access_event_id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id BIGINT UNSIGNED NOT NULL, site_id BIGINT UNSIGNED NOT NULL, vehicle_id BIGINT UNSIGNED NULL, visitor_visit_id BIGINT UNSIGNED NULL, employee_id BIGINT UNSIGNED NULL,
    event_type VARCHAR(100) NOT NULL, direction ENUM('ENTRY','EXIT') NOT NULL, authorization_status ENUM('AUTHORIZED','DENIED','PENDING') NOT NULL DEFAULT 'PENDING', denied_reason VARCHAR(500) NULL, occurred_at DATETIME NOT NULL, recorded_by_user_id BIGINT UNSIGNED NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT fk_access_events_company FOREIGN KEY (company_id) REFERENCES companies(company_id) ON DELETE CASCADE, CONSTRAINT fk_access_events_site FOREIGN KEY (site_id) REFERENCES sites(site_id) ON DELETE RESTRICT, CONSTRAINT fk_access_events_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(vehicle_id) ON DELETE SET NULL, CONSTRAINT fk_access_events_visitor_visit FOREIGN KEY (visitor_visit_id) REFERENCES visitor_visits(visitor_visit_id) ON DELETE SET NULL, CONSTRAINT fk_access_events_employee FOREIGN KEY (employee_id) REFERENCES employees(employee_id) ON DELETE SET NULL, CONSTRAINT fk_access_events_recorded_by FOREIGN KEY (recorded_by_user_id) REFERENCES users(user_id) ON DELETE SET NULL,
    INDEX idx_access_events_company_site_occurred (company_id,site_id,occurred_at), INDEX idx_access_events_company_status (company_id,authorization_status), INDEX idx_access_events_company_vehicle (company_id,vehicle_id), INDEX idx_access_events_company_visitor (company_id,visitor_visit_id), INDEX idx_access_events_company_employee (company_id,employee_id)
);